{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, the closest analogue (Morgan 0.2362), had a peak CSF:plasma ratio of only 0.12 in monkeys with little brain distribution, directly demonstrating poor CNS access for a large glycosylated polycyclic natural product; this transfers to doxorubicin's anthracycline glycoside architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "DX-52-1, a complex polycyclic natural product with polar/ionizable groups, showed a brain-to-blood ratio of about 0.02 in mice, indicating difficulty crossing the BBB; supports a fail prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Digitoxin, a multi-sugar cardiac glycoside, had a very low CSF/plasma ratio (0.01-0.03) in dogs, showing that large glycosides do not easily penetrate the BBB; supports a fail prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "SC-4453, another cardiac glycoside, had the lowest brain concentration at steady state in guinea pigs, consistent with BBB impermeability; supports a fail prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Emodin-8-O-β-D-glucoside, an anthraquinone glycoside, was detected in rat brain and classified as BBB-permeable; this is contradictory evidence, but its smaller monosaccharide structure and lack of the amino-sugar/polyhydroxylated side chain limit transfer to doxorubicin.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: doxorubicin is unlikely to achieve meaningful CNS access after systemic administration. The closest and most direct glycoside/polyketide evidence (mithramycin, DX-52-1, digitoxin, SC-4453) consistently shows poor brain/CSF penetration, while the permeable glycoside analogues are structurally more distant and do not outweigh the expected efflux and polar-surface liabilities.",
  "evidence_gaps": [
    "No direct doxorubicin brain/CSF measurement is present in the evidence set.",
    "All Morgan similarities are low (~0.20-0.24), so structural transfer is approximate.",
    "Cross-species and assay differences (monkey, mouse, dog, guinea pig; CSF vs tissue vs autoradiography) limit quantitative comparison."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

